// Embeds TradingView Lightweight Charts (static/vendor, Apache-2.0) as a string so the chart WebView works offline.
const fs = require('fs');
const path = require('path');
const src = fs.readFileSync(path.join(__dirname, '..', '..', 'static', 'vendor', 'lightweight-charts.js'), 'utf8');
fs.writeFileSync(path.join(__dirname, '..', 'src', 'components', 'chart', 'lwc-source.ts'),
  '/* eslint-disable */\n// Generated by scripts/vendor-lwc.js from static/vendor/lightweight-charts.js (TradingView Lightweight Charts v4, Apache-2.0).\nexport default ' + JSON.stringify(src) + ';\n');
console.log('lwc-source.ts', src.length);
